      "roteiro_projeto": "<div style='max-width:74ch;color:#f1f5f9;font-size:1.02rem;line-height:1.78;letter-spacing:0.015em;word-spacing:0.04em;'><div style='background:rgba(30,41,59,0.65);border-left:3px solid #6366f1;padding:10px 14px;border-radius:8px;margin-bottom:10px;'>1. <strong style='color:#e0e7ff;font-weight:700;'>Identifique</strong> o conceito de <em style='color:#cbd5e1;'>Artigos definidos e indefinidos</em> no enunciado.</div>\n<div style='background:rgba(30,41,59,0.65);border-left:3px solid #6366f1;padding:10px 14px;border-radius:8px;margin-bottom:10px;'>2. <strong style='color:#e0e7ff;font-weight:700;'>Separe</strong> os dados principais.</div>\n<div style='background:rgba(30,41,59,0.65);border-left:3px solid #6366f1;padding:10px 14px;border-radius:8px;margin-bottom:10px;'>3. <strong style='color:#e0e7ff;font-weight:700;'>Aplique</strong> a regra correspondente de INGLES.</div></div>"
